using System.Collections.Generic;

namespace C7GameData {
	// What a generated map was generated as: the world size's name, the
	// landform and the percent of the map that is water, as picked at setup
	// (see C7Engine.WorldCharacteristics). The Advanced AI tunes itself by
	// them (see C7Engine.AI.Advanced.AdvancedProfiles). Saved with the map;
	// null for a map that wasn't generated by the game (an imported Civ3
	// save or scenario) and for saves made before it was kept.
	public class MapGeneration {
		// The world size's name in the rules (Tiny, Small, Standard, Large,
		// Huge), or null for a size not from the rules.
		public string worldSize;
		// Archipelago, Continents or Pangaea.
		public string landform;
		// 60, 70 or 80.
		public int water;

		// The parts a profile key may name, the world size's first.
		public IEnumerable<string> Parts() {
			if (!string.IsNullOrEmpty(worldSize)) {
				yield return worldSize;
			}
			if (!string.IsNullOrEmpty(landform)) {
				yield return landform;
			}
			if (water > 0) {
				yield return water.ToString();
			}
		}

		// "Huge/Pangaea/70".
		public string Key => string.Join("/", Parts());

		public override string ToString() => Key;
	}
}
